static sc_integer main_region_Hornomicroondas_Operacion_Detenido_react(Statechart* handle, const sc_integer transitioned_before)
{
	/* The reactions of state Detenido. */
 			sc_integer transitioned_after = transitioned_before;
	if ((transitioned_after) < (0))
	{ 
		if (((handle->iface.startStop_raised) == bool_true) && ((statechart_is_state_active(handle, Statechart_main_region_Hornomicroondas_Puerta_Cerrada)) == bool_true))
		{ 
			exseq_main_region_Hornomicroondas_Operacion_Detenido(handle);
			enseq_main_region_Hornomicroondas_Operacion_Funcionando_default(handle);
			transitioned_after = 0;
		} 
	} 
	/* If no transition was taken */
	if ((transitioned_after) == (transitioned_before))
	{ 
		/* then execute local reactions. */
		if (((handle->timeEvents.statechart_main_region_Hornomicroondas_Operacion_Detenido_tev0_raised) == bool_true) && ((handle->iface.aviso_activo) == bool_true))
		{ 
			statechart_set_aviso_activo(handle, bool_false);
		} 
		if (handle->iface.abrir_puerta_raised == bool_true)
		{ 
			statechart_set_aviso_activo(handle, bool_false);
		} 
	} 
	return transitioned_after;
}

